#!/usr/bin/env node
// altalt — Alt (altalt.io) API 연동 설정 위저드.
// 결정적 단계(키 저장, MCP 등록)는 직접 처리하고, 코드 생성은 사용자의
// 코딩 에이전트(claude/codex)에 위임한다. 문서는 llms.txt URL로 참조해
// CLI 재배포 없이 항상 최신을 가리킨다.
import { execFileSync, spawnSync } from "node:child_process";
import { randomUUID } from "node:crypto";
import fs from "node:fs";
import os from "node:os";
import path from "node:path";
import { createInterface } from "node:readline/promises";
import { fileURLToPath, pathToFileURL } from "node:url";
import * as prompts from "@clack/prompts";
import { message } from "./i18n.js";

export let LLMS_URL = "https://altalt.io/llms.txt";
export let CONSOLE_URL = "https://altalt.io/account/integrations";
export let MCP_URL = "https://mcp.altalt.io/mcp";
export let API_URL = "https://public-api.altalt.io/v1";

const PROJECT_MARKERS = [
  "package.json",
  "pyproject.toml",
  "requirements.txt",
  "go.mod",
  "Gemfile",
  "Cargo.toml",
  "build.gradle",
  "build.gradle.kts",
  "pom.xml",
  "composer.json",
  "mix.exs",
];

const packagePath = fileURLToPath(new URL("../package.json", import.meta.url));
const VERSION = JSON.parse(fs.readFileSync(packagePath, "utf8")).version;
let devMode = false;

/** --dev: dev 스택(dev.altalt.io)으로 전환 — 릴리스 전 QA용. */
function enableDevMode() {
  devMode = true;
  LLMS_URL = "https://dev.altalt.io/llms.txt";
  CONSOLE_URL = "https://dev.altalt.io/account/integrations";
  MCP_URL = "https://mcp.dev.altalt.io/mcp";
  API_URL = "https://public-api.dev.altalt.io/v1";
}

// ---------- pure helpers (unit-tested) ----------

/** .env 본문에 KEY=value를 추가하거나 기존 줄을 교체한다. */
export function upsertEnv(content, key, value) {
  const line = `${key}=${value}`;
  const pattern = new RegExp(`^\\s*(?:export\\s+)?${key}\\s*=.*$`, "m");
  if (pattern.test(content)) return content.replace(pattern, line);
  if (content === "") return `${line}\n`;
  return `${content.replace(/\n?$/, "\n")}${line}\n`;
}

/** .env에서 KEY 값을 읽는다. 따옴표 제거 등 셸 평가는 하지 않는다. */
export function readEnvValue(content, key) {
  const pattern = new RegExp(`^\\s*(?:export\\s+)?${key}\\s*=\\s*(.*)\\s*$`, "m");
  return content.match(pattern)?.[1] ?? null;
}

/** 같은 디렉토리의 0600 임시 파일을 마지막 rename으로 원자적으로 교체한다. */
export function writeEnvFileAtomic(
  envPath,
  content,
  { fsImpl = fs, randomIdImpl = randomUUID } = {},
) {
  const tempPath = path.join(
    path.dirname(envPath),
    `.${path.basename(envPath)}.altalt-${randomIdImpl()}.tmp`,
  );
  try {
    fsImpl.writeFileSync(tempPath, content, { encoding: "utf8", mode: 0o600, flag: "wx" });
    fsImpl.renameSync(tempPath, envPath);
  } catch (error) {
    try {
      fsImpl.unlinkSync(tempPath);
    } catch {
      // rename 전 실패한 임시 파일이 없으면 정리할 것이 없다.
    }
    throw error;
  }
}

/** 명시적 옵션 또는 POSIX locale 환경 변수에서 CLI 표시 언어를 결정한다. */
export function resolveLocale(
  explicitLocale,
  env = process.env,
  runtimeLocale = Intl.DateTimeFormat().resolvedOptions().locale,
) {
  if (explicitLocale !== undefined && explicitLocale !== "ko" && explicitLocale !== "en") {
    throw new Error(message(resolveLocale(undefined, env, runtimeLocale), "invalidLanguage"));
  }
  if (explicitLocale) return explicitLocale;
  const systemLocale = env.LC_ALL || env.LC_MESSAGES || env.LANG || runtimeLocale || "";
  return /^ko(?:[_-]|$)/i.test(systemLocale) ? "ko" : "en";
}

const CLI_FLAG_NAMES = new Map([
  ["--dev", "dev"],
  ["--help", "help"],
  ["-h", "help"],
  ["--version", "version"],
  ["-v", "version"],
  ["--print-prompt", "printPrompt"],
  ["--verbose", "verbose"],
  ["--mcp-only", "mcpOnly"],
  ["--api-only", "apiOnly"],
]);

class CliArgumentError extends Error {
  constructor(key, variables = {}) {
    super(key);
    this.key = key;
    this.variables = variables;
  }
}

function parseCliArguments(args) {
  const flags = new Set();
  let explicitLocale;
  for (let index = 0; index < args.length; index += 1) {
    const argument = args[index];
    if (argument === "--lang" || argument.startsWith("--lang=")) {
      if (explicitLocale !== undefined) throw new CliArgumentError("duplicateOption", { option: "--lang" });
      const value = argument === "--lang" ? args[index + 1] : argument.slice("--lang=".length);
      if (value !== "ko" && value !== "en") throw new CliArgumentError("languageValueRequired");
      explicitLocale = value;
      if (argument === "--lang") index += 1;
      continue;
    }
    const name = CLI_FLAG_NAMES.get(argument);
    if (!name) throw new CliArgumentError("unknownOption", { option: argument });
    if (flags.has(name)) throw new CliArgumentError("duplicateOption", { option: argument });
    flags.add(name);
  }
  return { flags, explicitLocale };
}

function localeHintFromArguments(args) {
  for (let index = 0; index < args.length; index += 1) {
    const argument = args[index];
    const value = argument === "--lang" ? args[index + 1] : argument.startsWith("--lang=") ? argument.slice(7) : null;
    if (value === "ko" || value === "en") return value;
  }
  return undefined;
}

/** 개발 목적별 최소 권한과 검증 대상을 반환한다. */
export function getDeveloperAccessPlan(target) {
  const readScopes = ["notes:read", "transcripts:read", "summaries:read"];
  if (target === "api") {
    return {
      scopes: readScopes,
      checkNotes: true,
      checkTranscripts: true,
      checkSummaries: true,
      checkWebhooks: false,
    };
  }
  if (target === "webhooks") {
    return {
      scopes: ["webhooks:manage"],
      checkNotes: false,
      checkTranscripts: false,
      checkSummaries: false,
      checkWebhooks: true,
    };
  }
  if (target === "both") {
    return {
      scopes: [...readScopes, "webhooks:manage"],
      checkNotes: true,
      checkTranscripts: true,
      checkSummaries: true,
      checkWebhooks: true,
    };
  }
  throw new Error(message("en", "unknownDeveloperTarget", { target }));
}

const SUPPORTED_CLIENTS = [
  { id: "claude", label: "Claude Code" },
  { id: "codex", label: "Codex" },
  { id: "cursor", label: "Cursor" },
];

const CLIENT_INSTALL_URLS = {
  claude: "https://docs.anthropic.com/en/docs/claude-code/getting-started",
  codex: "https://help.openai.com/en/articles/11096431",
  cursor: "https://www.cursor.com/downloads",
};

export function getClientInstallUrl(clientId) {
  return CLIENT_INSTALL_URLS[clientId] ?? "https://altalt.io/developers/mcp";
}

/** 감지된 앱을 먼저, 나머지는 고정된 제품 순서로 나열한다. */
export function buildClientChoices(installedClientIds) {
  const installed = new Set(installedClientIds);
  return SUPPORTED_CLIENTS.map((client) => ({ ...client, installed: installed.has(client.id) })).sort(
    (left, right) => Number(right.installed) - Number(left.installed),
  );
}

/** OAuth MCP 등록에 쓰는 공개 명령. 토큰이나 API 키를 인자로 포함하지 않는다. */
export function buildOAuthMcpCommands(mcpUrl = MCP_URL, serverName = "alt") {
  return {
    claude: {
      get: ["mcp", "get", serverName],
      add: ["mcp", "add", "--transport", "http", serverName, mcpUrl],
    },
    codex: {
      get: ["mcp", "get", serverName],
      add: ["mcp", "add", serverName, "--url", mcpUrl],
      login: ["mcp", "login", serverName],
    },
  };
}

/** Cursor의 URL-only OAuth MCP 설치 딥링크를 충돌 없는 이름으로 만든다. */
export function buildCursorDeepLink(mcpUrl = MCP_URL, serverName = "alt-oauth") {
  const config = Buffer.from(JSON.stringify({ url: mcpUrl })).toString("base64");
  return `cursor://anysphere.cursor-deeplink/mcp/install?name=${encodeURIComponent(serverName)}&config=${encodeURIComponent(config)}`;
}

export function buildCursorConnectionName(randomIdImpl = randomUUID) {
  return `alt-oauth-${randomIdImpl().replaceAll("-", "").slice(0, 12)}`;
}

async function fetchApiJson(url, apiKey, fetchImpl, method = "GET", timeoutMs = 15_000) {
  const controller = new AbortController();
  const timeout = setTimeout(() => controller.abort(), timeoutMs);
  try {
    const response = await fetchImpl(url, {
      method,
      signal: controller.signal,
      headers: {
        Accept: "application/json",
        Authorization: `Bearer ${apiKey}`,
      },
    });
    let body = null;
    try {
      body = await response.json();
    } catch {
      // 오류 응답이 JSON이 아니어도 HTTP 상태로 진단을 계속한다.
    }
    if (!response.ok) {
      const error = body?.error;
      return {
        ok: false,
        status: response.status,
        code: typeof error?.code === "string" ? error.code : `http_${response.status}`,
        message: typeof error?.message === "string" ? error.message : `Request failed with HTTP ${response.status}`,
      };
    }
    return { ok: true, status: response.status, body };
  } catch (error) {
    return {
      ok: false,
      status: null,
      code: "network_error",
      message: error instanceof Error ? error.message : "Network request failed",
    };
  } finally {
    clearTimeout(timeout);
  }
}

/** API 키로 notes와 선택적인 webhook 읽기 권한을 변경 없이 점검한다. */
export async function inspectDeveloperAccess(
  apiKey,
  {
    apiBaseUrl = API_URL,
    checkNotes = true,
    checkTranscripts = false,
    checkSummaries = false,
    includeWebhooks = false,
    fetchImpl = globalThis.fetch,
  } = {},
) {
  let notes = null;
  let transcripts = null;
  let summaries = null;
  if (checkNotes) {
    const notesResult = await fetchApiJson(`${apiBaseUrl}/notes?limit=1`, apiKey, fetchImpl);
    const firstNote = Array.isArray(notesResult.body?.notes) ? notesResult.body.notes[0] : null;
    notes = notesResult.ok
      ? {
          ok: true,
          status: notesResult.status,
          count: Array.isArray(notesResult.body?.notes) ? notesResult.body.notes.length : null,
        }
      : notesResult;

    const inspectContent = async (kind) => {
      if (!notesResult.ok) return null;
      const noteId = typeof firstNote?.id === "string" ? firstNote.id : "altalt-scope-probe";
      const result = await fetchApiJson(
        `${apiBaseUrl}/notes/${encodeURIComponent(noteId)}/${kind}`,
        apiKey,
        fetchImpl,
      );
      // Public API authorization runs before note lookup, so not_found proves
      // the requested scope without requiring the account to contain a note.
      const contentNotReadyCode = kind === "transcript" ? "transcript_not_ready" : "summary_not_ready";
      if (
        result.ok ||
        (result.status === 404 && ["not_found", contentNotReadyCode].includes(result.code))
      ) {
        return { ok: true, status: result.status };
      }
      return result;
    };
    if (checkTranscripts) transcripts = await inspectContent("transcript");
    if (checkSummaries) summaries = await inspectContent("summary");
  }

  if (!includeWebhooks) return { notes, transcripts, summaries, webhooks: null };

  const webhookResult = await fetchApiJson(`${apiBaseUrl}/webhook-endpoints`, apiKey, fetchImpl);
  const webhooks = webhookResult.ok
    ? {
        ok: true,
        status: webhookResult.status,
        endpoints: Array.isArray(webhookResult.body?.endpoints) ? webhookResult.body.endpoints : [],
      }
    : webhookResult;
  return { notes, transcripts, summaries, webhooks };
}

/** 사용자가 선택한 기존 webhook endpoint에 명시적으로 test event를 보낸다. */
export async function sendWebhookTest(
  apiKey,
  endpointId,
  { apiBaseUrl = API_URL, fetchImpl = globalThis.fetch } = {},
) {
  const encodedId = encodeURIComponent(endpointId);
  const result = await fetchApiJson(
    `${apiBaseUrl}/webhook-endpoints/${encodedId}/test`,
    apiKey,
    fetchImpl,
    "POST",
  );
  if (!result.ok) return result;
  return { ok: true, status: result.status };
}

/** 프로젝트 디렉토리에서 스택 힌트를 수집한다 (에이전트 프롬프트에 넣는 용도). */
export function detectStack(dir) {
  const hints = [];
  const pkgPath = path.join(dir, "package.json");
  if (fs.existsSync(pkgPath)) {
    hints.push("Node.js");
    try {
      const pkg = JSON.parse(fs.readFileSync(pkgPath, "utf8"));
      const deps = { ...pkg.dependencies, ...pkg.devDependencies };
      for (const [dep, label] of [
        ["next", "Next.js"],
        ["react", "React"],
        ["express", "Express"],
        ["fastify", "Fastify"],
        ["hono", "Hono"],
        ["typescript", "TypeScript"],
      ]) {
        if (deps?.[dep]) hints.push(label);
      }
    } catch {
      // package.json이 깨져 있어도 위저드는 계속 진행한다
    }
  }
  if (fs.existsSync(path.join(dir, "pyproject.toml")) || fs.existsSync(path.join(dir, "requirements.txt"))) {
    hints.push("Python");
  }
  if (fs.existsSync(path.join(dir, "go.mod"))) hints.push("Go");
  if (fs.existsSync(path.join(dir, "Gemfile"))) hints.push("Ruby");
  if (fs.existsSync(path.join(dir, "Cargo.toml"))) hints.push("Rust");
  return hints;
}

function findGitRoot(dir) {
  try {
    return execFileSync("git", ["-C", dir, "rev-parse", "--show-toplevel"], {
      encoding: "utf8",
      stdio: ["ignore", "pipe", "ignore"],
    }).trim();
  } catch {
    return null;
  }
}

function isGitTracked(gitRoot, relativePath) {
  const options = { stdio: "ignore" };
  try {
    execFileSync("git", ["-C", gitRoot, "ls-files", "--error-unmatch", "--", relativePath], options);
    return true;
  } catch {
    return false;
  }
}

function isGitIgnored(gitRoot, relativePath) {
  const options = { stdio: "ignore" };
  try {
    execFileSync(
      "git",
      ["-C", gitRoot, "check-ignore", "--quiet", "--no-index", "--", relativePath],
      options,
    );
    return true;
  } catch {
    return false;
  }
}

function hasProjectMarker(dir) {
  return PROJECT_MARKERS.some((marker) => fs.existsSync(path.join(dir, marker)));
}

/** 에이전트에 넘길 프롬프트. 문서 페이지의 공통 프롬프트와 같은 내용 + 스택 힌트. */
export function buildAgentPrompt(stackHints) {
  const stackLine = stackHints.length > 0 ? ` The project stack looks like: ${stackHints.join(", ")}.` : "";
  return `Set up an Alt (altalt.io) integration in this project.

1. Fetch ${LLMS_URL} and follow it as the source of truth. It documents the REST API, webhooks, and the MCP server.
2. Ask me what I want to build (e.g. sync notes into a knowledge base, a webhook receiver), then implement it with this project's existing stack and conventions.${stackLine}
3. For MCP, prefer browser OAuth and do not ask for an API key unless the client lacks MCP OAuth. For REST or webhooks, read ALT_API_KEY from the environment (already stored in .env if I completed the wizard) — never hardcode it. If a key is missing, point me to ${CONSOLE_URL} and tell me which scopes to grant.`;
}

// ---------- interactive machinery ----------

function findBinary(name) {
  const probe = process.platform === "win32" ? "where" : "which";
  try {
    execFileSync(probe, [name], { stdio: "ignore" });
    return true;
  } catch {
    return false;
  }
}

export function openUrl(
  url,
  { platform = process.platform, spawnImpl = spawnSync } = {},
) {
  const [binary, args] =
    platform === "darwin"
      ? ["open", [url]]
      : platform === "win32"
        ? ["rundll32.exe", ["url.dll,FileProtocolHandler", url]]
        : ["xdg-open", [url]];
  try {
    const result = spawnImpl(binary, args, { stdio: "ignore" });
    return result.status === 0;
  } catch {
    // 브라우저를 못 열어도 URL은 이미 화면에 출력돼 있다
    return false;
  }
}

// 파이프 입력(비-TTY)은 readline이 대기 중 아닌 줄을 버리므로,
// 시작 시 stdin 전체를 읽어 큐로 소비한다 (스크립트 자동화도 가능해짐).
const scripted = !process.stdin.isTTY;
let scriptedAnswers = null;

function takeScriptedAnswer() {
  if (scriptedAnswers === null) {
    let raw = "";
    try {
      raw = fs.readFileSync(0, "utf8");
    } catch {
      // 읽을 수 없는 stdin은 입력 종료로 처리한다.
    }
    scriptedAnswers = raw === "" ? [] : raw.split(/\r?\n/);
    if (raw.endsWith("\n")) scriptedAnswers.pop();
  }
  if (scriptedAnswers.length === 0) return null;
  return scriptedAnswers.shift().trim();
}

export function formatSecretPrompt(promptText, answer) {
  return `${promptText}${answer === "" ? "" : "[hidden]"}\n`;
}

async function ask(rl, question) {
  if (scripted) {
    const answer = takeScriptedAnswer();
    if (answer === null) {
      process.stdout.write(question);
      throw new WizardInputEnded();
    }
    process.stdout.write(`${question}${answer}\n`);
    return answer;
  }
  return (await rl.question(question)).trim();
}

/** 자동화/테스트 입력의 비밀값은 화면에 원문을 남기지 않는다. */
function readScriptedSecret(promptText) {
  const answer = takeScriptedAnswer();
  if (answer === null) {
    process.stdout.write(promptText);
    throw new WizardInputEnded();
  }
  process.stdout.write(formatSecretPrompt(promptText, answer));
  return answer;
}

// 파이프가 먼저 닫혀도(예: `npx altalt | head`) 스택트레이스 없이 종료한다
process.stdout.on("error", (error) => {
  if (error?.code === "EPIPE") process.exit(0);
  throw error;
});

function log(message = "") {
  process.stdout.write(`${message}\n`);
}

class WizardCancelled extends Error {
  constructor() {
    super("Wizard cancelled");
    this.name = "WizardCancelled";
  }
}

class WizardInputEnded extends Error {
  constructor() {
    super("Wizard input ended");
    this.name = "WizardInputEnded";
  }
}

function createInteraction(rl, locale, { verbose = false } = {}) {
  const completed = [];
  async function select({ message: promptMessage, options, initialValue }) {
    if (!scripted) {
      const value = await prompts.select({ message: promptMessage, options, initialValue });
      if (prompts.isCancel(value)) throw new WizardCancelled();
      return value;
    }

    log(promptMessage);
    options.forEach((option, index) => {
      const hint = option.hint ? ` — ${option.hint}` : "";
      log(`  [${index + 1}] ${option.label}${hint}`);
    });
    const defaultIndex = Math.max(
      0,
      options.findIndex((option) => option.value === initialValue),
    );
    while (true) {
      const answer = await ask(rl, message(locale, "choose", { count: options.length, defaultIndex: defaultIndex + 1 }));
      const index = answer === "" ? defaultIndex : Number(answer) - 1;
      if (Number.isInteger(index) && options[index]) {
        log();
        return options[index].value;
      }
      log(message(locale, "invalidChoice"));
    }
  }

  async function confirm({ message: promptMessage, initialValue = true }) {
    if (!scripted) {
      const value = await prompts.confirm({
        message: promptMessage,
        active: message(locale, "yes"),
        inactive: message(locale, "no"),
        initialValue,
      });
      if (prompts.isCancel(value)) throw new WizardCancelled();
      return value;
    }
    const suffix = initialValue ? "[Y/n] " : "[y/N] ";
    const answer = await ask(rl, `${promptMessage} ${suffix}`);
    if (answer === "") return initialValue;
    return /^y/i.test(answer);
  }

  async function password({ message: promptMessage, allowEmpty = true }) {
    if (!scripted) {
      const value = await prompts.password({
        message: promptMessage,
        mask: "*",
        validate: allowEmpty ? undefined : (answer) => (!answer ? message(locale, "required") : undefined),
      });
      if (prompts.isCancel(value)) throw new WizardCancelled();
      return value.trim();
    }
    return readScriptedSecret(`${promptMessage}: `);
  }

  return { locale, verbose, completed, select, confirm, password, close: () => rl?.close() };
}

/** 앱 아이콘(public/alt_logo.png)의 'Alt' 텍스트 영역만 잘라 변환한 ASCII 아트 (46col×13row).
 *  재생성: 글자 bbox 자동탐지(면 안쪽 어두운 픽셀) → crop+pad24 → 46col,
 *  lum>0.62 = 공백, 어두울수록 " .;:coxkKXNWM" 진한 문자((0.62-lum)/0.27 스트레치).
 *  문자 밝기 인덱스가 곧 회색조 — ANSI 256 그레이 램프로 착색(라이트/다크 겸용 클램프). */
const ICON_ROWS = [
  "          .cxxxx           ;cxK",
  "          oWMMMMc          :KMM      cxkc",
  "         cXMx:KWW          :KMW     .xMWx",
  "        :xMN  xXWX         :KMW     :KMWK  .",
  "        oWW:   kNWx        :KMW   KXNWMWNNNM",
  "       cXWK    cKWW.       :KMW     :kMWk",
  "      :kMN      xNWN       :KMW      xMWx",
  "     .oMNo      .oWWk      :KMW     .xMWx",
  "     cNMWXXNNNNNXXMWW;     :KMW      xMWx",
  "    cKMNc.;....;.:kNWW     :KMW      xMWx",
  "   ;xMWx          .kWWK    :KMW     .xMWk",
  "   oMMN            oXMMo   :KMM      KWMNo.:",
  "  cxkK              xkkK   ;xkK       :kXNNN",
];

const SHADE_CHARS = " .;:coxkKXNWM";
const GRAY_LO = 239;
const GRAY_HI = 251;

function printLogo(locale) {
  const color = process.stdout.isTTY && !process.env.NO_COLOR;
  const RESET = "\x1b[0m";
  log();
  for (const row of ICON_ROWS) {
    if (!color) {
      log(row);
      continue;
    }
    let line = "";
    let lastGray = -1;
    for (const ch of row) {
      if (ch === " ") {
        line += ch;
        continue;
      }
      const idx = Math.max(0, SHADE_CHARS.indexOf(ch));
      const gray = GRAY_LO + Math.round((idx * (GRAY_HI - GRAY_LO)) / (SHADE_CHARS.length - 1));
      if (gray !== lastGray) {
        line += `\x1b[38;5;${gray}m`;
        lastGray = gray;
      }
      line += ch;
    }
    log(line + RESET);
  }
  log();
  const bold = (s) => (color ? `\x1b[1m${s}\x1b[0m` : s);
  const dim = (s) => (color ? `\x1b[2m${s}\x1b[0m` : s);
  log(
    ` ${bold(message(locale, "title"))}  ${dim(`· https://altalt.io/developers${devMode ? `  [${message(locale, "devStack")}]` : ""}`)}`,
  );
  log();
}

// ---------- wizard steps ----------

async function stepDeveloperTarget(ui) {
  return ui.select({
    message: message(ui.locale, "developerQuestion"),
    options: [
      {
        value: "api",
        label: message(ui.locale, "apiConnection"),
        hint: message(ui.locale, "apiHint"),
      },
      {
        value: "webhooks",
        label: message(ui.locale, "webhooks"),
        hint: message(ui.locale, "webhooksHint"),
      },
      {
        value: "both",
        label: message(ui.locale, "both"),
      },
    ],
    initialValue: "api",
  });
}

function cleanTerminalText(value, maxLength = 160) {
  return String(value ?? "")
    .replace(/[\u0000-\u001f\u007f-\u009f\u200b-\u200f\u202a-\u202e\u2066-\u2069\ufeff]/g, "")
    .slice(0, maxLength);
}

function logAccessFailure(label, result, logImpl = log, { locale = "en", verbose = false } = {}) {
  const status = result.status === null ? "network" : `HTTP ${result.status}`;
  logImpl(message(locale, "accessCheckFailed", { label }));
  if (verbose) {
    logImpl(`  ${status} · ${cleanTerminalText(result.code)} · ${cleanTerminalText(result.message)}`);
  }
}

export async function maybeSendWebhookTest(
  ui,
  apiKey,
  endpoints,
  { sendTestImpl = sendWebhookTest, logImpl = log } = {},
) {
  const locale = ui?.locale ?? "en";
  if (endpoints.length === 0) {
    logImpl(message(locale, "webhookNone"));
    return;
  }

  logImpl(message(locale, "webhookCount", { count: endpoints.length }));
  const visible = endpoints.slice(0, 10);
  if (endpoints.length > visible.length) {
    logImpl(message(locale, "webhookVisible", { visible: visible.length, count: endpoints.length }));
  }
  const wantsTest = await ui.confirm({
    message: message(locale, "webhookSendQuestion"),
    initialValue: false,
  });
  if (!wantsTest) return;

  const selectedId = await ui.select({
    message: message(locale, "webhookChoose"),
    options: visible.map((endpoint) => ({
      value: endpoint.id,
      label: cleanTerminalText(endpoint?.url ?? message(locale, "urlUnavailable")),
      hint: cleanTerminalText(endpoint?.status ?? message(locale, "statusUnknown")),
    })),
    initialValue: visible[0]?.id,
  });
  const endpoint = visible.find((candidate) => candidate.id === selectedId);
  if (!endpoint || typeof endpoint.id !== "string") return;
  const confirmation = await ui.confirm({
    message: message(locale, "webhookConfirm", { url: cleanTerminalText(endpoint.url ?? endpoint.id) }),
    initialValue: false,
  });
  if (!confirmation) return;

  const result = await sendTestImpl(apiKey, endpoint.id);
  if (result.ok) {
    logImpl(message(locale, "webhookSent", { status: result.status }));
    ui.completed?.push({ label: message(locale, "webhookSentSummary") });
  }
  else {
    ui.failed = true;
    logAccessFailure(message(locale, "webhookTest"), result, logImpl, ui);
  }
}

export async function stepApiKey(
  ui,
  cwd,
  {
    target = "both",
    openUrlImpl = openUrl,
    inspectImpl = inspectDeveloperAccess,
    webhookStepImpl = maybeSendWebhookTest,
    logImpl = log,
  } = {},
) {
  const locale = ui?.locale ?? "en";
  const plan = getDeveloperAccessPlan(target);
  const heading =
    target === "api"
      ? message(locale, "apiConnection")
      : target === "webhooks"
        ? message(locale, "webhookSetup")
        : message(locale, "apiAndWebhookSetup");
  logImpl(`── ${heading} ──`);
  logImpl(message(locale, "scopeInstruction"));
  plan.scopes.forEach((scope) => logImpl(`  • ${scope}`));
  const wantsOpen = await ui.confirm({
    message: message(locale, "openConsole"),
    initialValue: true,
  });
  if (wantsOpen && !openUrlImpl(CONSOLE_URL)) {
    logImpl(message(locale, "browserOpenFailed"));
    logImpl(CONSOLE_URL);
  }
  const key = await ui.password({
    message: message(locale, "pasteApiKey"),
  });
  if (key === "") {
    logImpl(message(locale, "skipped"));
    return null;
  }
  if (!key.startsWith("alt_live_")) {
    logImpl(message(locale, "unusualApiKey"));
  }

  logImpl(message(locale, "checkingKey"));
  const access = await inspectImpl(key, {
    checkNotes: plan.checkNotes,
    checkTranscripts: plan.checkTranscripts,
    checkSummaries: plan.checkSummaries,
    includeWebhooks: plan.checkWebhooks,
  });
  const requiredChecks = [
    { enabled: plan.checkNotes, label: message(locale, "restApi"), result: access.notes },
    {
      enabled: plan.checkTranscripts,
      label: message(locale, "transcriptAccess"),
      result: access.transcripts,
    },
    {
      enabled: plan.checkSummaries,
      label: message(locale, "summaryAccess"),
      result: access.summaries,
    },
    {
      enabled: plan.checkWebhooks,
      label: message(locale, "webhookAccess"),
      result: access.webhooks,
    },
  ];
  const failedCheck = requiredChecks.find(({ enabled, result }) => enabled && !result?.ok);
  if (failedCheck) {
    ui.failed = true;
    logAccessFailure(failedCheck.label, failedCheck.result, logImpl, ui);
    logImpl(message(locale, "keyUnchanged"));
    return null;
  }

  if (plan.checkNotes) {
    const verificationKey =
      access.notes.count === null
        ? "apiVerified"
        : access.notes.count === 1
          ? "apiVerifiedOneNote"
          : "apiVerifiedManyNotes";
    logImpl(message(locale, verificationKey, { count: access.notes.count }));
  }
  if (plan.checkTranscripts || plan.checkSummaries) {
    logImpl(message(locale, "contentVerified"));
  }
  if (plan.checkWebhooks) logImpl(message(locale, "webhookVerified"));

  const gitRoot = findGitRoot(cwd);
  const projectDir = gitRoot ?? cwd;
  let projectReady = true;
  if (gitRoot === null && !hasProjectMarker(cwd)) {
    ui.failed = true;
    projectReady = false;
    logImpl(message(locale, "notProject"));
    logImpl(message(locale, "rerunInProject"));
  } else {
    try {
      const envPath = path.join(projectDir, ".env");
      const envStats = fs.lstatSync(envPath, { throwIfNoEntry: false });
      if (envStats?.isSymbolicLink()) {
        ui.failed = true;
        logImpl(message(locale, "symlinkEnvRefused", { path: envPath }));
        logImpl(message(locale, "noFileChange"));
        return null;
      }
      const existing = envStats ? fs.readFileSync(envPath, "utf8") : "";
      const existingKey = readEnvValue(existing, "ALT_API_KEY");
      const envTracked = gitRoot !== null && isGitTracked(gitRoot, ".env");
      if (envTracked) {
        ui.failed = true;
        projectReady = false;
        logImpl(message(locale, "trackedEnvRefused", { path: envPath }));
        logImpl(message(locale, "noFileChange"));
      } else if (existingKey === key) {
        fs.chmodSync(envPath, 0o600);
        ui.completed?.push({ label: message(locale, "keyFileSecured") });
        logImpl(message(locale, "keyAlreadyStored", { path: envPath }));
      } else {
        logImpl(message(locale, "keyCanStore"));
        logImpl(`  ${envPath}`);
        logImpl(message(locale, "keyHidden"));
        const shouldStore = await ui.confirm({
          message: message(locale, "storeQuestion"),
          initialValue: true,
        });
        let canWrite = shouldStore;
        if (canWrite && existingKey !== null && existingKey !== key) {
          canWrite = await ui.confirm({
            message: message(locale, "replaceQuestion"),
            initialValue: false,
          });
        }
        if (canWrite) {
          writeEnvFileAtomic(envPath, upsertEnv(existing, "ALT_API_KEY", key));
          ui.completed?.push({ label: message(locale, "keyStoredSummary") });
          logImpl(message(locale, "keyStored", { path: envPath }));
        } else {
          logImpl(message(locale, "noFileChange"));
        }
      }

      if (gitRoot !== null && !envTracked && fs.existsSync(envPath)) {
        if (!isGitIgnored(gitRoot, ".env")) {
          logImpl(message(locale, "gitignoreWarning"));
        }
      }
    } catch (error) {
      ui.failed = true;
      logImpl(message(locale, "fileSetupFailed"));
      if (ui.verbose) logImpl(`  ${cleanTerminalText(error?.message ?? error)}`);
      return null;
    }
  }
  if (access.webhooks?.ok) await webhookStepImpl(ui, key, access.webhooks.endpoints);
  logImpl();
  return projectReady ? key : null;
}

function commandSucceeded(binary, args, stdio = "ignore") {
  return spawnSync(binary, args, { stdio }).status === 0;
}

function inspectMcpServer(binary, args) {
  const result = spawnSync(binary, args, {
    encoding: "utf8",
    stdio: ["ignore", "pipe", "pipe"],
  });
  if (result.status === 0) return { state: "existing" };
  const output = `${result.stdout ?? ""}\n${result.stderr ?? ""}`;
  if (result.status === 1 && /No MCP server named\b/i.test(output)) return { state: "missing" };
  return {
    state: "error",
    status: result.status,
    detail: result.stderr?.trim() || result.stdout?.trim() || result.error?.message || "",
  };
}

export function isClientInstalled(
  clientId,
  {
    platform = process.platform,
    homeDir = os.homedir(),
    env = process.env,
    existsImpl = fs.existsSync,
    findBinaryImpl = findBinary,
  } = {},
) {
  if (findBinaryImpl(clientId)) return true;
  if (clientId !== "cursor") return false;
  if (platform === "darwin") {
    return ["/Applications/Cursor.app", path.join(homeDir, "Applications", "Cursor.app")].some(existsImpl);
  }
  if (platform === "win32") {
    return [
      env.LOCALAPPDATA && path.join(env.LOCALAPPDATA, "Programs", "cursor", "Cursor.exe"),
      env.ProgramFiles && path.join(env.ProgramFiles, "Cursor", "Cursor.exe"),
    ].some((candidate) => candidate && existsImpl(candidate));
  }
  if (platform === "linux") {
    return [
      path.join(homeDir, ".local", "share", "applications", "cursor.desktop"),
      "/usr/local/share/applications/cursor.desktop",
      "/usr/share/applications/cursor.desktop",
    ].some(existsImpl);
  }
  return false;
}

async function chooseMcpServer(ui, binary, clientLabel, baseCommands, parallelCommands) {
  const baseInspection = inspectMcpServer(binary, baseCommands.get);
  if (baseInspection.state === "error") return { error: baseInspection };
  if (baseInspection.state === "missing") {
    const parallelInspection = inspectMcpServer(binary, parallelCommands.get);
    if (parallelInspection.state === "error") return { error: parallelInspection };
    if (parallelInspection.state === "existing") {
      return { commands: parallelCommands, serverName: "alt-oauth", existing: true };
    }
    return { commands: baseCommands, serverName: "alt", existing: false };
  }

  const choice = await ui.select({
    message: message(ui.locale, "existingConnection", { client: clientLabel }),
    options: [
      {
        value: "existing",
        label: message(ui.locale, "useExisting"),
        hint: message(ui.locale, "noSettingsChange"),
      },
      {
        value: "oauth",
        label: message(ui.locale, "addBrowserLogin"),
      },
    ],
    initialValue: "existing",
  });
  if (choice === "existing") {
    return { commands: baseCommands, serverName: "alt", existing: true };
  }
  const parallelInspection = inspectMcpServer(binary, parallelCommands.get);
  if (parallelInspection.state === "error") return { error: parallelInspection };
  if (parallelInspection.state === "existing") {
    return { commands: parallelCommands, serverName: "alt-oauth", existing: true };
  }
  return { commands: parallelCommands, serverName: "alt-oauth", existing: false };
}

async function setupSelectedClient(ui, clientId) {
  if (clientId === "cursor") {
    const deepLink = buildCursorDeepLink(MCP_URL, buildCursorConnectionName());
    if (!openUrl(deepLink)) {
      ui.failed = true;
      log(message(ui.locale, "cursorOpenFailed"));
      log("https://altalt.io/developers/mcp");
      return { ok: false, label: "Cursor" };
    }
    log(message(ui.locale, "cursorOpened"));
    return { ok: true, label: "Cursor", status: "approvalRequired" };
  }

  const label = clientId === "claude" ? "Claude Code" : "Codex";
  const baseCommands = buildOAuthMcpCommands()[clientId];
  const parallelCommands = buildOAuthMcpCommands(MCP_URL, "alt-oauth")[clientId];
  const registration = await chooseMcpServer(ui, clientId, label, baseCommands, parallelCommands);
  if (registration.error) {
    ui.failed = true;
    log(message(ui.locale, "clientInspectionFailed", { client: label }));
    if (ui.verbose) {
      if (typeof registration.error.status === "number") {
        log(`  ${message(ui.locale, "exitStatus", { status: registration.error.status })}`);
      }
      if (registration.error.detail) log(`  ${cleanTerminalText(registration.error.detail)}`);
    }
    return { ok: false, label };
  }
  if (registration.existing) {
    log(message(ui.locale, "keepingConnection", { client: label }));
    return { ok: true, label, status: "existing" };
  }

  const stdio = ui.verbose ? "inherit" : "ignore";
  if (!commandSucceeded(clientId, registration.commands.add, stdio)) {
    ui.failed = true;
    log(message(ui.locale, "clientSetupFailed", { client: label }));
    log(message(ui.locale, "checkBrowserLogin"));
    log("https://altalt.io/developers/mcp");
    return { ok: false, label };
  }

  log(message(ui.locale, "clientSetupDone", { client: label }));
  if (clientId === "claude") {
    log(message(ui.locale, "claudeLogin"));
  } else {
    log(message(ui.locale, "codexLogin", { server: registration.serverName }));
  }
  return { ok: true, label, status: "configured" };
}

export function copyTextToClipboard(
  value,
  { platform = process.platform, spawnImpl = spawnSync } = {},
) {
  const commands =
    platform === "darwin"
      ? [["pbcopy", []]]
      : platform === "win32"
        ? [["clip", []]]
        : [
            ["wl-copy", []],
            ["xclip", ["-selection", "clipboard"]],
            ["xsel", ["--clipboard", "--input"]],
          ];
  for (const [binary, args] of commands) {
    try {
      const result = spawnImpl(binary, args, {
        input: value,
        encoding: "utf8",
        stdio: ["pipe", "ignore", "ignore"],
      });
      if (result.status === 0) {
        return true;
      }
    } catch {
      // Try the next platform clipboard command, then fall back to manual copy.
    }
  }
  return false;
}

export async function stepGenericRemoteMcp(
  ui,
  { copyImpl = copyTextToClipboard, logImpl = log } = {},
) {
  const locale = ui?.locale ?? "en";
  logImpl(`── ${message(locale, "otherAppHeading")} ──`);
  logImpl(message(locale, "otherAppIntro"));
  logImpl(`  ${MCP_URL}`);
  const shouldCopy = await ui.confirm({
    message: message(locale, "copyMcpQuestion"),
    initialValue: true,
  });
  if (shouldCopy) {
    logImpl(copyImpl(MCP_URL) ? message(locale, "mcpCopied") : message(locale, "mcpCopyFailed"));
  }
  logImpl(message(locale, "otherAppInstructions"));
  return { ok: true, label: message(locale, "otherApp"), status: "manualSetupRequired" };
}

export function hasRemainingConnectionOption(installedIds, handled) {
  return (
    !handled.has("generic-mcp") || installedIds.some((clientId) => !handled.has(clientId))
  );
}

export function completionStatus(locale, item, stopped = false) {
  if (item.status === "manualSetupRequired") return message(locale, "manualSetupRequired");
  if (item.status === "approvalRequired") return message(locale, "approvalRequired");
  if (item.status === "existing") return message(locale, "usingExisting");
  if (stopped) return message(locale, "completedKept");
  return message(locale, "setupComplete");
}

function logStoppedItems(ui, locale) {
  if (ui.completed.length === 0) {
    log(message(locale, "noChanges"));
    return;
  }
  ui.completed.forEach((item) => {
    log(`✓ ${item.label} — ${completionStatus(locale, item, true)}`);
  });
}

async function stepMcp(ui) {
  const installedIds = SUPPORTED_CLIENTS.filter((client) => isClientInstalled(client.id)).map(
    (client) => client.id,
  );
  const completed = [];
  const handled = new Set();

  while (true) {
    const choices = buildClientChoices(installedIds).filter((client) => !handled.has(client.id));
    const clientOption = (client) => ({
      value: client.id,
      label: client.label,
      hint: client.installed
        ? message(ui.locale, "installed")
        : message(ui.locale, "installGuide"),
    });
    const options = [
      ...choices.filter((client) => client.installed).map(clientOption),
      ...(handled.has("generic-mcp")
        ? []
        : [
            {
              value: "generic-mcp",
              label: message(ui.locale, "otherApp"),
              hint: message(ui.locale, "otherAppHint"),
            },
          ]),
      ...choices.filter((client) => !client.installed).map(clientOption),
    ];
    options.push({ value: "done", label: message(ui.locale, "finish") });

    if (installedIds.length === 0 && handled.size === 0) {
      log(message(ui.locale, "noApps"));
      log(message(ui.locale, "installFirst"));
    }

    const selected = await ui.select({
      message: message(ui.locale, "connectWhere"),
      options,
      initialValue: options[0]?.value ?? "done",
    });
    if (selected === "done") break;

    let result;
    if (selected === "generic-mcp") {
      result = await stepGenericRemoteMcp(ui);
    } else {
      const selectedClient = choices.find((client) => client.id === selected);
      if (!selectedClient?.installed) {
        const installUrl = getClientInstallUrl(selected);
        if (!openUrl(installUrl)) {
          log(installUrl);
        }
        handled.add(selected);
        continue;
      }
      result = await setupSelectedClient(ui, selected);
    }

    handled.add(selected);
    if (result.ok) {
      completed.push(result);
      ui.completed?.push(result);
    }

    if (!hasRemainingConnectionOption(installedIds, handled)) break;
    const next = await ui.select({
      message: message(ui.locale, "nextAction"),
      options: [
        { value: "finish", label: message(ui.locale, "finish") },
        { value: "another", label: message(ui.locale, "connectAnother") },
      ],
      initialValue: "finish",
    });
    if (next === "finish") break;
  }

  if (completed.length > 0) {
    log();
    for (const item of completed) {
      log(`✓ ${item.label} — ${completionStatus(ui.locale, item)}`);
    }
    log();
    log(message(ui.locale, "testPrompt"));
  }
  return completed;
}

export async function stepHandoff(
  ui,
  cwd,
  {
    agents = [
      { bin: "claude", label: "Claude Code" },
      { bin: "codex", label: "Codex" },
    ].filter((agent) => findBinary(agent.bin)),
    spawnImpl = spawnSync,
    logImpl = log,
  } = {},
) {
  const locale = ui?.locale ?? "en";
  const prompt = buildAgentPrompt(detectStack(cwd));
  if (agents.length === 0) {
    const showPrompt = await ui.confirm({
      message: message(locale, "noAgentPrompt"),
      initialValue: false,
    });
    if (showPrompt) {
      logImpl();
      logImpl(prompt);
      logImpl();
    }
    return false;
  }
  const wantsHandoff = await ui.confirm({
    message: message(locale, "handoffQuestion"),
    initialValue: false,
  });
  if (!wantsHandoff) {
    return false;
  }
  let agent = agents[0];
  if (agents.length > 1) {
    const selected = await ui.select({
      message: message(locale, "agentQuestion"),
      options: agents.map((candidate) => ({ value: candidate.bin, label: candidate.label })),
      initialValue: agents[0].bin,
    });
    agent = agents.find((candidate) => candidate.bin === selected) ?? agents[0];
  }
  ui.close?.();
  logImpl(message(locale, "launchingAgent", { agent: agent.label }));
  const result = spawnImpl(agent.bin, [prompt], { stdio: "inherit" });
  if (result.status !== 0) {
    ui.failed = true;
    logImpl(message(locale, "agentFailed", { agent: agent.label }));
    if (ui.verbose) {
      if (typeof result.status === "number") {
        logImpl(`  ${message(locale, "exitStatus", { status: result.status })}`);
      }
      if (result.error) logImpl(`  ${cleanTerminalText(result.error.message)}`);
    }
    logImpl(message(locale, "pastePrompt"));
    logImpl(prompt);
    logImpl();
    return false;
  }
  return true;
}

async function main() {
  const args = process.argv.slice(2);
  let parsed;
  try {
    parsed = parseCliArguments(args);
  } catch (error) {
    const locale = resolveLocale(localeHintFromArguments(args));
    if (error instanceof CliArgumentError) {
      log(message(locale, error.key, error.variables));
    } else {
      log(message(locale, "unexpectedError"));
    }
    process.exitCode = 1;
    return;
  }
  if (parsed.flags.has("dev")) enableDevMode();
  const locale = resolveLocale(parsed.explicitLocale);
  const verbose = parsed.flags.has("verbose");
  if (parsed.flags.has("help")) {
    log(message(locale, "help"));
    return;
  }
  if (parsed.flags.has("version")) {
    log(VERSION);
    return;
  }
  if (parsed.flags.has("printPrompt")) {
    log(buildAgentPrompt(detectStack(process.cwd())));
    return;
  }

  const cwd = process.cwd();
  printLogo(locale);

  const mcpOnly = parsed.flags.has("mcpOnly");
  const apiOnly = parsed.flags.has("apiOnly");
  if (mcpOnly && apiOnly) throw new Error(message(locale, "exclusiveFlags"));

  // scripted 모드에서는 readline이 stdin을 선점해 큐 읽기를 망치므로 만들지 않는다
  const rl = scripted ? null : createInterface({ input: process.stdin, output: process.stdout });
  const ui = createInteraction(rl, locale, { verbose });
  try {
    let audience = mcpOnly ? "easy" : apiOnly ? "developer" : null;
    if (audience === null) {
      const answer = await ui.select({
        message: message(locale, "audienceQuestion"),
        options: [
          {
            value: "easy",
            label: message(locale, "no"),
            hint: message(locale, "noHint"),
          },
          {
            value: "developer",
            label: message(locale, "yes"),
            hint: message(locale, "yesHint"),
          },
          {
            value: "unsure",
            label: message(locale, "unsure"),
            hint: message(locale, "unsureHint"),
          },
        ],
        initialValue: "easy",
      });
      audience = answer === "developer" ? "developer" : "easy";
    }

    if (audience === "easy") {
      await stepMcp(ui);
      if (ui.failed) process.exitCode = 1;
      return;
    }

    const developerTarget = await stepDeveloperTarget(ui);
    const key = await stepApiKey(ui, cwd, { target: developerTarget });
    if (key) await stepHandoff(ui, cwd);
    if (ui.failed) process.exitCode = 1;
  } catch (error) {
    if (error instanceof WizardInputEnded) {
      log();
      log(message(locale, "inputEnded"));
      logStoppedItems(ui, locale);
      process.exitCode = 1;
      return;
    }
    if (error instanceof WizardCancelled) {
      log();
      log(message(locale, "cancelled"));
      logStoppedItems(ui, locale);
      return;
    }
    log(message(locale, "unexpectedError"));
    if (verbose) log(`  ${cleanTerminalText(error?.message ?? error)}`);
    process.exitCode = 1;
    return;
  } finally {
    rl?.close();
  }
}

const isMain =
  process.argv[1] !== undefined &&
  import.meta.url === pathToFileURL(fs.realpathSync(process.argv[1])).href;
if (isMain) {
  main().catch((error) => {
    console.error(error?.message ?? error);
    process.exit(1);
  });
}
